51: // ------------------------------------------------------------------ audio
52: class AudioEngine {
53:   constructor() {
54:     this.ctx = null;
55:     this.master = null;
56:     this.musicBus = null;
57:     this.sfxBus = null;
58:     this.musicVolume = 65;
59:     this.sfxVolume = 75;
60:     this.ambientTimer = 0;
61:     this.step = 0;
62:     this.notes = [523.25, 659.25, 783.99, 659.25, 587.33, 493.88, 440.0, 493.88];
63:   }
64: 
65:   ensure() {
66:     if (this.ctx) {
67:       if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
68:       return this.ctx;
69:     }
70:     const AudioCtx = window.AudioContext || window.webkitAudioContext;
71:     if (!AudioCtx) return null;
72:     try {
73:       const ctx = new AudioCtx();
74:       this.ctx = ctx;
75:       this.master = ctx.createGain();
76:       this.master.gain.value = 0.72;
77:       this.master.connect(ctx.destination);
78: 
79:       this.musicBus = ctx.createGain();
80:       this.musicBus.gain.value = 0;
81:       this.musicBus.connect(this.master);
82:       this.sfxBus = ctx.createGain();
83:       this.sfxBus.gain.value = 0;
84:       this.sfxBus.connect(this.master);
85: 
86:       this.startAmbient();
87:       this.applyVolume('music', this.musicVolume);
88:       this.applyVolume('sfx', this.sfxVolume);
89:       if (ctx.state === 'suspended') ctx.resume().catch(() => {});
90:     } catch {
91:       this.ctx = null;
92:     }
93:     return this.ctx;
94:   }
95: 
96:   startAmbient() {
97:     const ctx = this.ctx;
98:     if (!ctx || this.ambientTimer) return;
99:     const now = ctx.currentTime;
100: 
101:     // Warm, slowly breathing pad.
102:     const filter = ctx.createBiquadFilter();
103:     filter.type = 'lowpass';
104:     filter.frequency.value = 880;
105:     filter.Q.value = 0.7;
106:     filter.connect(this.musicBus);
107: 
108:     const pad = ctx.createGain();
109:     pad.gain.setValueAtTime(0.0001, now);
110:     pad.gain.exponentialRampToValueAtTime(0.18, now + 5);
111:     pad.connect(filter);
112: 
113:     for (const [freq, detune, amp] of [[130.81, -4, 0.5], [196.0, 3, 0.36], [261.63, 0, 0.3], [329.63, 5, 0.18]]) {
114:       const osc = ctx.createOscillator();
115:       osc.type = 'sine';
116:       osc.frequency.value = freq;
117:       osc.detune.value = detune;
118:       const g = ctx.createGain();
119:       g.gain.value = amp;
120:       osc.connect(g);
121:       g.connect(pad);
122:       osc.start();
123:     }
124: 
125:     const lfo = ctx.createOscillator();
126:     lfo.frequency.value = 0.055;
127:     const lfoGain = ctx.createGain();
128:     lfoGain.gain.value = 0.075;
129:     lfo.connect(lfoGain);
130:     lfoGain.connect(pad.gain);
131:     lfo.start();
132: 
133:     // A very quiet sea wash under the music.
134:     const len = Math.floor(ctx.sampleRate * 5);
135:     const buffer = ctx.createBuffer(1, len, ctx.sampleRate);
136:     const data = buffer.getChannelData(0);
137:     let last = 0;
138:     for (let i = 0; i < len; i++) {
139:       const white = Math.random() * 2 - 1;
140:       last = last * 0.985 + white * 0.015;
141:       data[i] = last * 2.4;
142:     }
143:     const sea = ctx.createBufferSource();
144:     sea.buffer = buffer;
145:     sea.loop = true;
146:     const seaFilter = ctx.createBiquadFilter();
147:     seaFilter.type = 'lowpass';
148:     seaFilter.frequency.value = 680;
149:     const seaGain = ctx.createGain();
150:     seaGain.gain.value = 0.085;
151:     sea.connect(seaFilter);
152:     seaFilter.connect(seaGain);
153:     seaGain.connect(this.musicBus);
154:     sea.start();
155: 
156:     this.ambientTimer = window.setInterval(() => this.pluck(), 3100);
157:   }
158: 
159:   pluck() {
160:     const ctx = this.ctx;
161:     if (!ctx || ctx.state !== 'running') return;
162:     const freq = this.notes[this.step++ % this.notes.length];
163:     const now = ctx.currentTime + 0.02;
164:     const osc = ctx.createOscillator();
165:     osc.type = 'triangle';
166:     osc.frequency.value = freq;
167:     const gain = ctx.createGain();
168:     gain.gain.setValueAtTime(0.0001, now);
169:     gain.gain.exponentialRampToValueAtTime(0.065, now + 0.04);
170:     gain.gain.exponentialRampToValueAtTime(0.0001, now + 1.8);
171:     const filter = ctx.createBiquadFilter();
172:     filter.type = 'lowpass';
173:     filter.frequency.value = 1800;
174:     osc.connect(gain);
175:     gain.connect(filter);
176:     filter.connect(this.musicBus);
177:     osc.start(now);
178:     osc.stop(now + 1.9);
179:   }
180: 
181:   applyVolume(kind, value) {
182:     const v = clamp(Number(value) || 0, 0, 100) / 100;
183:     if (kind === 'music') {
184:       this.musicVolume = Number(value) || 0;
185:       if (this.musicBus) this.musicBus.gain.setTargetAtTime(v * 0.62, this.ctx.currentTime, 0.25);
186:     } else {
187:       this.sfxVolume = Number(value) || 0;
188:       if (this.sfxBus) this.sfxBus.gain.setTargetAtTime(v * 0.72, this.ctx.currentTime, 0.12);
189:     }
190:   }
191: 
192:   setVolume(kind, value) {
193:     if (!this.ctx) {
194:       if (kind === 'music') this.musicVolume = value;
195:       else this.sfxVolume = value;
196:       return;
197:     }
198:     this.ensure();
199:     this.applyVolume(kind, value);
200:   }
201: 
202:   tone(freq, { at = 0, dur = 0.14, type = 'sine', gain = 0.16, slide = 0 } = {}) {
203:     const ctx = this.ensure();
204:     if (!ctx) return;
205:     const now = ctx.currentTime + at;
206:     const osc = ctx.createOscillator();
207:     osc.type = type;
208:     osc.frequency.setValueAtTime(freq, now);
209:     if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30, freq + slide), now + dur);
210:     const g = ctx.createGain();
211:     g.gain.setValueAtTime(0.0001, now);
212:     g.gain.exponentialRampToValueAtTime(gain, now + Math.min(0.035, dur * 0.3));
213:     g.gain.exponentialRampToValueAtTime(0.0001, now + dur);
214:     osc.connect(g);
215:     g.connect(this.sfxBus);
216:     osc.start(now);
217:     osc.stop(now + dur + 0.03);
218:   }
219: 
220:   sfx(kind) {
221:     switch (kind) {
222:       case 'success':
223:         [523.25, 659.25, 783.99].forEach((f, i) => this.tone(f, { at: i * 0.075, dur: 0.24, gain: 0.13 }));
224:         break;
225:       case 'error':
226:         this.tone(196, { dur: 0.2, type: 'sawtooth', gain: 0.09, slide: -55 });
227:         break;
228:       case 'start':
229:         [261.63, 329.63, 392.0, 523.25].forEach((f, i) => this.tone(f, { at: i * 0.09, dur: 1.1, gain: 0.11 }));
230:         break;
231:       case 'open':
232:         this.tone(660, { dur: 0.09, gain: 0.1 });
233:         this.tone(990, { at: 0.04, dur: 0.11, gain: 0.06 });
234:         break;
235:       case 'pause':
236:         this.tone(392, { dur: 0.16, gain: 0.09 });
237:         break;
238:       default:
239:         this.tone(520, { dur: 0.07, gain: 0.08 });
240:     }
241:   }
242: }
