472: function disposeModel(model) {
473:   if (!model?.group) return;
474:   model.group.traverse((child) => {
475:     if (child.geometry) child.geometry.dispose?.();
476:     if (child.material) {
477:       if (Array.isArray(child.material)) child.material.forEach((m) => m.dispose?.());
478:       else child.material.dispose?.();
479:     }
480:   });
481: }
