484:   const previous = creatorPreview;
485:   const group = new THREE.Group();
486:   const model = buildCharacter(appearance);
487:   model.group.position.set(0, 0, 0);
488:   group.add(model.group);
489:   group.rotation.y = creatorYaw;
490:   group.visible = mode === 'creator';
491:   creatorScene.add(group);
492:   creatorPreview = { group, model };
493: 
494:   if (previous) {
495:     creatorScene.remove(previous.group);
496:     disposeModel(previous.model);
497:   }
498:   return creatorPreview;
499: }
