560:     if (!creatorDrag) {
561:       creatorIdle += dt;
562:       if (creatorIdle > 1.2) creatorYaw += dt * 0.055;
563:     }
564:     if (creatorPreview) {
565:       creatorPreview.group.rotation.y = creatorYaw;
566:       creatorPreview.model.update(dt, 0);
567:     }
568:     renderer.render(creatorScene, creatorCamera);
569:   } else {
570:     game.update(dt);
