460:     this.updateCamera(dt);
461:     this.world.update(dt, {
462:       hour: this.state.hour,
463:       weather: this.state.weather,
464:       playerPos: this.player.group.position,
465:       camera: this.camera,
466:       playerSpeed: movingSpeed
467:     });
468:     this.world.ctx.playerYaw = this.player.group.rotation.y;
469: 
470:     this.hudTimer += dt;
471:     if (this.hudTimer > 0.24) {
472:       this.hudTimer = 0;
473:       this.ui.renderHUD();
474:     }
475:     this.interactionTimer += dt;
476:     if (this.interactionTimer > 0.12) {
477:       this.interactionTimer = 0;
478:       this.refreshPrompt();
479:     }
480:     this.minimapTimer += dt;
481:     if (this.minimapTimer > 0.5) {
482:       this.minimapTimer = 0;
483:       this.ui.drawMinimap();
484:     }
485:     this.autosaveTimer += dt;
486:     if (this.autosaveTimer > 45) {
487:       this.autosaveTimer = 0;
488:       if (!busy) this.save(false);
489:     }
490:   }
491: 
492:   updateMovement(dt) {
493:     let ix = 0;
494:     let iy = 0;
495:     if (this.keys.has('w') || this.keys.has('arrowup')) iy += 1;
496:     if (this.keys.has('s') || this.keys.has('arrowdown')) iy -= 1;
497:     if (this.keys.has('d') || this.keys.has('arrowright')) ix += 1;
498:     if (this.keys.has('a') || this.keys.has('arrowleft')) ix -= 1;
499:     ix += this.joystick.x;
500:     iy += this.joystick.y;
501:     const len = Math.hypot(ix, iy);
502:     if (len < 0.08) {
503:       this.player.update(dt, 0);
504:       return 0;
505:     }
506:     if (len > 1) { ix /= len; iy /= len; }
507: 
508:     const forwardX = -Math.sin(this.cameraYaw);
509:     const forwardZ = -Math.cos(this.cameraYaw);
510:     const rightX = Math.cos(this.cameraYaw);
511:     const rightZ = -Math.sin(this.cameraYaw);
512:     const vx = forwardX * iy + rightX * ix;
513:     const vz = forwardZ * iy + rightZ * ix;
514:     const speed = WALK_SPEED * Math.min(1, Math.hypot(ix, iy));
515:     const step = speed * dt;
516:     const group = this.player.group;
517:     let x = group.position.x;
518:     let z = group.position.z;
519:     const nx = x + vx * step;
520:     if (!this.world.isBlocked(nx, z)) x = nx;
521:     const nz = z + vz * step;
522:     if (!this.world.isBlocked(x, nz)) z = nz;
523:     group.position.x = x;
524:     group.position.z = z;
525: 
526:     if (Math.abs(vx) + Math.abs(vz) > 0.02) {
527:       const targetYaw = Math.atan2(vx, vz);
528:       let diff = ((targetYaw - group.rotation.y + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
529:       group.rotation.y += diff * Math.min(1, dt * 12);
530:     }
531:     this.player.update(dt, speed);
532:     this.state.player.x = x;
533:     this.state.player.z = z;
534:     this.state.player.yaw = group.rotation.y;
535:     return speed;
536:   }
