538:   updateCamera(dt) {
539:     const p = this.player.group.position;
540:     this.tmpTarget.set(p.x, 1.35, p.z);
541:     this.cameraTarget.lerp(this.tmpTarget, Math.min(1, dt * 9));
542:     if (this.cameraTarget.lengthSq() === 0) this.cameraTarget.copy(this.tmpTarget);
543:     const cos = Math.cos(this.cameraPitch);
544:     this.tmpPos.set(
545:       this.cameraTarget.x + Math.sin(this.cameraYaw) * cos * this.cameraDistance,
546:       Math.max(0.8, this.cameraTarget.y + Math.sin(this.cameraPitch) * this.cameraDistance),
547:       this.cameraTarget.z + Math.cos(this.cameraYaw) * cos * this.cameraDistance
548:     );
549:     this.camera.position.lerp(this.tmpPos, Math.min(1, dt * 9));
550:     this.camera.lookAt(this.cameraTarget);
551:   }
