553:   // ---------------------------------------------------------------- clock / needs
554:   advanceTime(hours, decay = true) {
555:     if (!hours || hours <= 0) return;
556:     const dayBefore = this.state.day;
557:     this.state.hour += hours;
558:     let days = 0;
559:     while (this.state.hour >= 24) {
560:       this.state.hour -= 24;
561:       this.state.day++;
562:       days++;
563:     }
564:     if (decay) this.decayNeeds(hours);
565:     if (this.state.day !== dayBefore) this.onNewDay(days);
566:   }
