568:   onNewDay() {
569:     this.state.weather = this.rollWeather();
570:     this.state.needWarnings = {};
571:     this.ui.banner(t('banner.day', { day: this.state.day }), t('banner.newDay'), t('banner.newDayDesc'), 4200);
572:     this.ui.toast(t('toast.newDay', { day: this.state.day }), 'success');
573:     window.setTimeout(() => {
574:       if (this.active) this.ui.toast(t('toast.weather', { weather: weatherName(this.state.weather) }));
575:     }, 900);
576:     this.save(false);
577:   }
578: 
579:   rollWeather() {
580:     const r = Math.random();
581:     if (r < 0.2) return 'rain';
582:     if (r < 0.5) return 'cloudy';
583:     return 'sunny';
584:   }
585: 
586:   decayNeeds(hours) {
587:     const traits = new Set(this.state.traits || []);
588:     const night = this.state.hour >= 22 || this.state.hour < 6;
589:     const rates = { ...NEED_RATES };
590:     if (traits.has('athlete')) rates.energy *= 0.72;
591:     if (traits.has('nightowl') && night) rates.energy *= 0.5;
592:     if (traits.has('gourmet')) rates.hunger *= 1.42;
593:     if (traits.has('social')) rates.social *= 0.62;
594:     if (traits.has('dreamer')) rates.fun *= 0.68;
595:     for (const key of Object.keys(rates)) {
596:       const need = this.state.needs;
597:       need[key] = clamp(need[key] - rates[key] * hours, 0, 100);
598:     }
599:     this.checkNeedWarnings();
600:     if (this.state.needs.energy <= 0.01) this.collapse();
601:   }
602: 
603:   checkNeedWarnings() {
604:     const warnings = this.state.needWarnings || (this.state.needWarnings = {});
605:     for (const key of Object.keys(this.state.needs)) {
606:       const v = this.state.needs[key];
607:       if (v <= 22 && !warnings[key]) {
608:         warnings[key] = true;
609:         this.ui.toast(t(`need.${key}.low`), 'warn');
610:       } else if (v > 34 && warnings[key]) {
611:         warnings[key] = false;
612:       }
613:     }
614:   }
