616:   collapse() {
617:     if (!this.active) return;
618:     const oldDay = this.state.day;
619:     if (this.state.hour >= 6) this.state.day++;
620:     this.state.hour = 7;
621:     this.state.player.x = START.x;
622:     this.state.player.z = START.z;
623:     this.state.player.yaw = START.yaw;
624:     this.state.needs.energy = 58;
625:     this.state.needs.hunger = Math.max(10, this.state.needs.hunger - 10);
626:     if (this.player) {
627:       this.player.group.position.set(START.x, 0, START.z);
628:       this.player.group.rotation.y = START.yaw;
629:     }
630:     this.syncCameraToPlayer(true);
631:     this.state.needWarnings = {};
632:     this.ui.toast(t('toast.collapse'), 'warn');
633:     if (this.state.day !== oldDay) this.onNewDay();
634:     this.afterChange();
635:     this.save(false);
636:   }
