638:   moodKey() {
639:     const n = this.state.needs;
640:     const avg = (n.energy + n.hunger + n.hygiene + n.social + n.fun) / 5;
641:     if (avg >= 82) return 'radiant';
642:     if (avg >= 68) return 'happy';
643:     if (avg >= 50) return 'content';
644:     if (avg >= 34) return 'tired';
645:     if (avg >= 18) return 'low';
646:     return 'miserable';
