649:   // ---------------------------------------------------------------- interaction
650:   refreshPrompt() {
651:     if (!this.active || this.ui.busy) { this.ui.hidePrompt(); return; }
652:     const pos = this.state.player;
653:     let best = null;
654:     let bestScore = Infinity;
655: 
656:     for (const spot of SPOTS) {
657:       if (spot.dlc && this.state.dlc[spot.dlc] === false) continue;
658:       const d = Math.hypot(pos.x - spot.x, pos.z - spot.z);
659:       if (d <= spot.radius + 1.35 && d - spot.radius < bestScore) {
660:         bestScore = d - spot.radius;
661:         best = { type: 'spot', spot };
662:       }
663:     }
664:     for (const npc of NPCS) {
665:       const live = this.world.ctx.npcs?.find((n) => n.id === npc.id);
666:       const p = live?.pos || { x: npc.home[0], z: npc.home[1] };
667:       const d = Math.hypot(pos.x - p.x, pos.z - p.z);
668:       if (d < 2.7 && d - 1.6 < bestScore) {
669:         bestScore = d - 1.6;
670:         best = { type: 'npc', npc };
671:       }
672:     }
673: 
674:     if (!best) {
675:       this.interaction = null;
676:       this.lastPromptSignature = '';
677:       this.ui.hidePrompt();
678:       return;
679:     }
680:     const id = best.type === 'spot' ? best.spot.id : best.npc.id;
681:     const sig = best.type + ':' + id;
682:     this.interaction = best;
683:     if (sig !== this.lastPromptSignature) {
684:       this.lastPromptSignature = sig;
685:       if (best.type === 'spot') {
686:         this.ui.showPrompt(best.spot, null);
687:         if (!this.state.discovered.includes(best.spot.id)) {
688:           this.state.discovered.push(best.spot.id);
689:           this.ui.toast(t('location.discovered', { name: t('h.' + best.spot.id) }), 'success');
690:         }
691:       } else {
692:         this.ui.showPrompt(null, best.npc);
693:       }
694:     }
695:   }
