736:     if (this.state.lastWorkDay === this.state.day) return { ok: false, reason: t('action.alreadyWorked') };
737:     if (this.state.hour < 9 || this.state.hour >= 17) return { ok: false, reason: t('toast.offDuty') };
738:     if (CAREERS[this.state.career.id].dlc && this.state.dlc[CAREERS[this.state.career.id].dlc] === false) {
739:       return { ok: false, reason: t('action.needDlc', { dlc: t('dlc.' + CAREERS[this.state.career.id].dlc + '.name') }) };
