744:   getSpotActions(spotId) {
745:     const list = [];
746:     if (this.state.career && CAREERS[this.state.career.id]?.spot === spotId) {
747:       const check = this.canWork();
748:       list.push({
749:         id: 'work', icon: 'briefcase', work: true,
