752:         state: this.state.lastWorkDay === this.state.day ? t('hud.shiftToday') : t('hud.shiftReady'),
753:         locked: !check.ok, lockNote: check.ok ? '' : check.reason
754:       });
755:     }
756: 
757:     for (const def of SPOT_ACTIONS[spotId] || []) {
