784:     if (def.id === 'adoptCat') return `${t('a.adopt')} · ${PETS.cat.name}`;
785:     if (def.id === 'playPet') return t('a.playPet', { pet: this.petName() || PETS.dog.name });
786:     if (def.id === 'wedding') return t('r.wedding');
787:     return t('a.' + def.id);
