796:   actionLock(spotId, def) {
797:     if (def.special === 'wardrobe') return { locked: false, lockNote: '' };
798:     if (def.requiresDlc && this.state.dlc[def.requiresDlc] === false) {
799:       return {
800:         locked: true,
801:         lockNote: t('action.needDlc', { dlc: t('dlc.' + def.requiresDlc + '.name') })
802:       };
803:     }
804:     if (def.cost && this.state.money < def.cost) {
805:       return { locked: true, lockNote: t('action.notEnough') };
806:     }
807:     if (def.requiresCareer && this.state.career?.id !== def.requiresCareer) {
808:       return { locked: true, lockNote: t('action.needCareer') };
809:     }
810:     if (def.special === 'adopt') {
811:       if (this.state.pet) return { locked: true, lockNote: t('toast.petAdoptedAlready') };
812:     }
813:     if (def.special === 'playPet') {
814:       if (!this.state.pet) return { locked: true, lockNote: t('toast.petNeeded') };
815:     }
816:     if (def.special === 'date') {
817:       const target = this.dateCandidate();
818:       if (!target) return { locked: true, lockNote: t('r.dateNeed') };
819:     }
820:     if (def.special === 'propose') {
821:       if (this.state.engagedTo) return { locked: true, lockNote: t('toast.engagedAlready') };
822:       if (this.state.marriedTo) return { locked: true, lockNote: t('toast.marriedAlready') };
823:       const target = this.proposeCandidate();
824:       if (!target) return { locked: true, lockNote: t('r.proposeNeed') };
825:     }
826:     if (def.special === 'wedding') {
827:       if (!this.state.engagedTo) return { locked: true, lockNote: t('r.proposeNeed') };
828:       if (this.state.money < (def.cost || 0)) return { locked: true, lockNote: t('action.notEnough') };
829:     }
830:     return { locked: false, lockNote: '' };
831:   }
