833:   performAction(spotId, actionId) {
834:     if (!this.active || !this.state) return;
835:     if (actionId === 'apply') { this.ui.openCareer(spotId); return; }
836:     if (actionId === 'changeOutfit') { this.ui.openWardrobe(); return; }
837:     if (actionId === 'work') { this.workShift(spotId); return; }
838:     const def = this.actionDef(spotId, actionId);
839:     if (!def) return;
840:     const lock = this.actionLock(spotId, def);
841:     if (lock.locked) {
842:       this.ui.toast(lock.lockNote || t('action.wrongPlace'), 'warn');
843:       this.sfx('error');
844:       return;
845:     }
846:     if (def.special === 'sleep') { this.sleep(); return; }
847:     if (def.special === 'date') { this.autoDate(); return; }
848:     if (def.special === 'propose') { this.autoPropose(); return; }
849:     if (def.special === 'wedding') { this.autoWedding(); return; }
850:     if (def.cost && this.state.money < def.cost) {
851:       this.ui.toast(t('action.notEnough'), 'warn');
852:       this.sfx('error');
853:       return;
854:     }
855: 
856:     this.ui.showProgress({
857:       kicker: t('action.started'),
858:       title: this.actionName(def),
859:       desc: this.actionDesc(def),
860:       duration: def.hours >= 3 ? 1850 : def.hours >= 2 ? 1650 : 1350,
861:       onDone: () => {
862:         if (def.cost) this.state.money -= def.cost;
863:         this.advanceTime(def.hours || 0, true);
864:         this.applyAction(def, spotId);
865:         if (def.pay) {
866:           this.state.money += def.pay;
867:           this.ui.toast(def.toast ? t(def.toast, { pay: def.pay }) : t('action.moneyGain', { n: def.pay }), 'success');
868:         } else if (def.toast) {
869:           this.ui.toast(t(def.toast, { pet: this.petName() }), 'success');
870:         } else {
871:           this.ui.toast(t('toast.actionDone', { action: this.actionName(def) }), 'success');
872:         }
873:         this.sfx('success');
874:         this.afterChange();
875:         this.save(false);
876:       }
877:     });
878:   }
