883:       for (const [key, value] of Object.entries(def.setNeeds)) n[key] = clamp(value, 0, 100);
884:     }
885:     if (def.needs) {
886:       for (const [key, value] of Object.entries(def.needs)) n[key] = clamp(n[key] + value, 0, 100);
