895:     if (def.special === 'adopt') this.adoptPet(def.petType);
896:     if (def.special === 'playPet' && this.state.pet) {
897:       this.ui.toast(t('toast.petPlay', { pet: this.petName() }), 'success');
898:     }
899:     if (def.groceries) this.state.groceries = true;
